extern "C" char *strcpy(char *, const char *);

class stringx {
    char *chars;
    void *my_buf;
public:
    stringx(const char *, int = -1);
    ~stringx();
    stringx &operator=(const stringx &);
    const char *c_str() const { return chars; }
};

enum {
    GT_PadCircle = 8,
    GT_PadCross = 9,
    GT_PadTriangle = 10,
    GT_PadSquare = 11,
    GT_PadBack = 18
};

extern stringx ksGlobalButtonArray[];

class IGOHintManager {
public:
    void process_help_string(stringx &dest, const char *source);
};

void IGOHintManager::process_help_string(stringx &dest, const char *source)
{
	char temp[80];
	int index = 0;

	strcpy(temp, source);

	while (temp[index] != 0)
	{
		if (temp[index] == '@')
		{
			char insert[3];
			switch (temp[index + 1])
			{
			case 'T':
				strcpy(insert, ksGlobalButtonArray[GT_PadTriangle].c_str());
				break;
			case 'S':
				strcpy(insert, ksGlobalButtonArray[GT_PadSquare].c_str());
				break;
			case 'C':
				strcpy(insert, ksGlobalButtonArray[GT_PadCircle].c_str());
				break;
			case 'X':
				strcpy(insert, ksGlobalButtonArray[GT_PadCross].c_str());
				break;
			case 'B':
				strcpy(insert, ksGlobalButtonArray[GT_PadBack].c_str());
				break;
			default:
				break;
			}

			temp[index] = insert[0];
			temp[index + 1] = insert[1];
		}

		index++;
	}

	dest = temp;
}
